  limit: '10kb',
  parameterLimit: 1000,
}));
```
**Issue:** While the sizes themselves are set conservatively (which is good), they should be configurable via environment variables for different deployment scenarios.

**Fix Needed:**
```javascript
const JSON_LIMIT = process.env.JSON_LIMIT || '10kb';
const PARAM_LIMIT = parseInt(process.env.PARAM_LIMIT) || 1000;

app.use(express.json({
  limit: JSON_LIMIT,
  strict: true,
}));
